-- ═══════════════════════════════════════════════════════════════
-- PATEL MARKETING CATALOGUE — SEED DATA
-- 406 products · 517 variants
-- Run AFTER 01_schema.sql
-- ═══════════════════════════════════════════════════════════════
begin;
truncate variants, products restart identity cascade;



select setval('products_id_seq', (select max(id) from products));
commit;

-- verify
select b.name brand, count(*) products from products p join brands b on b.id=p.brand_id group by 1 order by 2 desc;